#!/bin/bash

# Serial 10: off-the-shelf models over the study's languages, on both evaluation domains.
# No connector is trained, so this is a plain model x dataset cross product. Pairs with
# serial 11 (eval_lalm_decoder_txf.sh), which uses the same configs.

# The eval datasets come from the registry, not an inline list. It is generated by
# tools/preprocess/create_yamls_worldspeech_lalm.py and carries use_in_sweep, which is DERIVED:
# a config that is some cell's training-time selection split is not a held-out eval and is
# excluded there, once, rather than by hand in each script.
REGISTRY="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)/tools/preprocess/eval_datasets.csv"
if [ ! -f "$REGISTRY" ]; then
    echo "ERROR: $REGISTRY is missing." >&2
    echo "Run: python tools/preprocess/create_yamls_worldspeech_lalm.py" >&2
    exit 1
fi
# Header-driven so a column reorder cannot silently shift what is read.
mapfile -t SWEPT < <(awk -F, '
    { sub(/\r$/, "") }
    NR==1 { for (i=1; i<=NF; i++) { if ($i=="config_yaml") c=i; if ($i=="use_in_sweep") u=i }; next }
    $u=="True" { print $c }' "$REGISTRY")
DATASET_CONFIGS=("${SWEPT[@]}")

# whisper-medium is the study's own encoder, so it is the like-for-like reference; the other two
# are the commercial LALMs. Other Whisper sizes answer a scaling question this study is not
# asking. The instruct variant of Qwen2-Audio is absent because it performs badly here.
MODEL_CONFIGS=(
    "whisper_medium.yaml"
    "voxtral_mini_3b.yaml"
    "qwen_2_audio_7b.yaml"
)

models=''

VALID_ARGS=$(getopt -o '' --long models: -- "$@")
if [[ $? -ne 0 ]]; then
    exit 1;
fi

eval set -- "$VALID_ARGS"
while [ : ]; do
  case "$1" in
    --models)
        models=${2}
        shift 2
        ;;
    --) shift;
        break
        ;;
  esac
done

if [ -n "$models" ]; then
    read -ra MODEL_CONFIGS <<< "$models"
fi

# --eval_metrics is explicit because the upstream default is ['wer_all'] alone, so CER would
# not be computed. The training runs report CER, and a reader will expect the two to meet.
base_cmd="python -m tools.evaluate --serial 10 --batch_size 128 \
    --eval_metrics wer_all cer \
    --wandb_entity LisTAya \
    --wandb_project LALMDecoder"

for model_cfg in "${MODEL_CONFIGS[@]}"; do
    for dataset_cfg in "${DATASET_CONFIGS[@]}"; do
        cmd="$base_cmd --config configs/models/$model_cfg configs/datasets/$dataset_cfg"
        echo "$cmd"
        $cmd
    done
done
